/// <summary>
/// Extension of table <t>MarkupAutoLine</t>
/// </summary>
[ExtensionOf(tableStr(MarkupAutoLine))]
final class AVAMarkupAutoLineDbt_Extension
{
}

Method.Source:
/// <summary>
/// Extension of modifiedField method
/// </summary>
/// <param name = "_fieldId">field id</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldnum(MarkupAutoLine, MarkupCategory) :
            if (this.MarkupCategory == MarkupCategory::Pcs 
                || this.MarkupCategory == MarkupCategory::Percent)
            {
                // commentary added to trigger deployment - FINTHI
                this.Keep = NoYes::Yes;
            }
            else
            {
                this.Keep = NoYes::No;
            }
            break;
    }
}

/// <summary>
/// Extension of validateWrite method
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if(this.AVAFromDate != dateNull()
        && (this.MarkupCategory == MarkupCategory::Pcs
            || this.MarkupCategory == MarkupCategory::Percent))
    {
        ret = ret && this.avaCheckDatePeriod();
    }

    return ret;
}

/// <summary>
/// find MarkupAutoLine record by RecId
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>MarkupAutoLine</returns>
public static MarkupAutoLine avaFindByRecId(
    RecId _recId,
    boolean _selectForUpdate = false)
{
    MarkupAutoLine markupAutoLineLoc;

    if(_selectForUpdate)
    {
        markupAutoLineLoc.selectForUpdate(true);
    }

    select firstonly markupAutoLineLoc
        where markupAutoLineLoc.RecId == _recId;

    return markupAutoLineLoc;
}

/// <summary>
/// returns the related <t>MarkupAutoTable</t> record
/// </summary>
/// <returns>MarkupAutoTable</returns>
public MarkupAutoTable avaMarkupAutoTable()
{
    MarkupAutoTable avaMarkupAutoTable;

    select firstonly avaMarkupAutoTable
        where avaMarkupAutoTable.TableId == this.TableTableId
        && avaMarkupAutoTable.RecId == this.TableRecId;

    return avaMarkupAutoTable;
}

/// <summary>
/// find record
/// </summary>
/// <param name = "_tableRecId">recid of prent Table</param>
/// <param name = "_tableId">tableId</param>
/// <param name = "_linenum">lineNum</param>
/// <param name = "_forupdate">for update</param>
/// <returns>MarkupAutoLine record</returns>
public static MarkupAutoLine findByTableRecIdTableIdLineNum(RecId _tableRecId, TableId _tableId, Linenum _linenum, boolean _forupdate = false)
{
    MarkupAutoLine lMarkupAutoLine;

    lMarkupAutoLine.selectForUpdate(_forupdate);

    select firstonly lMarkupAutoLine
        where lMarkupAutoLine.TableRecId == _tableRecId
            && lMarkupAutoLine.TableTableId == _tableId
            && lMarkupAutoLine.LineNum == _linenum;

    return lMarkupAutoLine;
}

/// <summary>
/// Extension of method update
/// </summary>
public void  update()
{
    FromDate fromDateLoc = this.orig().AVAFromDate;

    next update();

    if(this.AVAFromDate != dateNull()
        && fromDateLoc == dateNull())
    {
        this.avaClosePreviousAutoMarkup();
    }
}

/// <summary>
/// Extension of method insert
/// </summary>
public void  insert()
{
    next insert();

    if(this.AVAFromDate != dateNull())
    {
        this.avaClosePreviousAutoMarkup();
    }
}

/// <summary>
/// closes all markupAutolines with empty AVAToDate that have the same TableRecId/TableTableId/CurrencyCode/MarkupCode/MarkupCategory/TaxGroup/InventSiteId/InventLocationId
/// </summary>
public void avaClosePreviousAutoMarkup()
{
    MarkupAutoLine avaAutoLine;

    ttsbegin;

    update_recordset avaAutoLine
        setting AVAToDate = DateTimeUtil::addDays(this.AVAFromDate, -1)
        where avaAutoLine.TableRecId    == this.TableRecId
        && avaAutoLine.TableTableId     == this.TableTableId
        && avaAutoLine.CurrencyCode     == this.CurrencyCode
        && avaAutoLine.MarkupCode       == this.MarkupCode
        && avaAutoLine.MarkupCategory   == this.MarkupCategory
        && avaAutoLine.TaxGroup         == this.TaxGroup
        && avaAutoLine.InventSiteId     == this.InventSiteId
        && avaAutoLine.InventLocationId == this.InventLocationId
        && avaAutoLine.AVAToDate        == dateNull()
        && avaAutoLine.RecId            != this.RecId;

    ttscommit;
}

/// <summary>
/// checks if a similar record within the Date period or same Start Date exists
/// </summary>
/// <returns>boolean</returns>
public boolean avaCheckDatePeriod()
{
    MarkupAutoLine avaAutoLine;

    select firstonly avaAutoLine
        where avaAutoLine.TableRecId    == this.TableRecId
        && avaAutoLine.TableTableId     == this.TableTableId
        && avaAutoLine.RecId            != this.RecId
        && avaAutoLine.CurrencyCode     == this.CurrencyCode
        && avaAutoLine.MarkupCode       == this.MarkupCode
        && avaAutoLine.MarkupCategory   == this.MarkupCategory
        && avaAutoLine.TaxGroup         == this.TaxGroup
        && avaAutoLine.InventSiteId     == this.InventSiteId
        && avaAutoLine.InventLocationId == this.InventLocationId
        && (avaAutoLine.AVAFromDate     == this.AVAFromDate
            || (avaAutoLine.AVAFromDate < this.AVAFromDate
                && avaAutoLine.AVAToDate >= this.AVAFromDate));

    if(avaAutoLine.RecId)
    {
        return checkFailed("@NDX:NXAMarkupAutoLineDateCheck");//;
    }
    else
    {
        return true;
    }
}

/// <summary>
/// display method to show priceUnit
/// </summary>
/// <returns>PriceUnit</returns>
display public PriceUnit avaPriceUnit()
{
    PriceUnit avaPriceUnit = 0;  
    InventTable avaInventTable;
    MarkupAutoTable avaMarkupAutoTable = this.avaMarkupAutoTable();

    if(avaMarkupAutoTable.ItemCode == TableGroupAll::Table)
    {
        avaInventTable = InventTable::find(avaMarkupAutoTable.ItemRelation);
    }

    if(avaInventTable
        && this.ModuleType == MarkupModuleType::Cust)
    {
        avaPriceUnit = avaInventTable.inventTableModuleSales().priceUnit();
    }
    else if(avaInventTable
        && this.ModuleType == MarkupModuleType::Vend)
    {
        avaPriceUnit = avaInventTable.inventTableModulePurch().priceUnit();
    }
    else if(avaInventTable
        && this.ModuleType == MarkupModuleType::Invent)
    {
        avaPriceUnit = avaInventTable.inventTableModuleInvent().priceUnit();
    }

    return avaPriceUnit;
}
